            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Hast thou not torn the Naiad from her flood, The Elfin from the green grass, and from me The summer dream beneath the tamarind tree?", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Music, when combined with a pleasurable idea, is poetry; music without the idea is simply music; the idea without the music is prose from its very definitiveness.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Thy Naiad airs have brought me home To the glory that was Greece And the grandeur that was Rome.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "If I could dwell Where Israfel Hath dwelt, and he where I, He might not sing so wildly well A mortal melody, While a bolder note than this might swell From my lyre within the sky.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Convinced myself, I seek not to convince.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "And as, in ethics, Evil is a consequence of Good, so, in fact, out of Joy is sorrow born. Either the memory of past bliss is the anguish of to-day, or the agonies which are, have their origin in the ecstasies which might have been.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "A carpet is the soul of an apartment.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Few persons can be made to believe that it is not quite an easy thing to invent a method of secret writing which shall baffle investigation. Yet it may be roundly asserted that human ingenuity cannot concoct a cipher which human ingenuity cannot resolve.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "They who dream by day are cognizant of many things which escape those who dream only by night.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "The best chess-player in Christendom may be little more than the best player of chess; but proficiency in whist implies capacity for success in all these more important undertakings where mind struggles with mind.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "To observe attentively is to remember distinctly.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "And Darkness and Decay and the Red Death held illimitable dominion over all.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "While the angels, all pallid and wan, Uprising, unveiling, affirm That the play is the tragedy, \"Man\", And its hero the Conqueror Worm.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Man is an animal that diddles, and there is no animal that diddles but man.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "The boundaries which divide Life from Death are at best shadowy and vague. Who shall say where the one ends, and where the other begins?", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "For the love of God Montresor!", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "I became insane, with long intervals of horrible sanity.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Can it be fancied that Deity ever vindictively Made in his image a mannikin merely to madden it?", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Depend upon it, after all, Thomas, Literature is the most noble of professions. In fact, it is about the only one fit for a man. For my own part, there is no seducing me from the path.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Gaily bedight, A gallant knight, In sunshine and in shadow, Had journeyed long, Singing a song, In search of Eldorado.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Over the Mountains Of the Moon, Down the Valley of the Shadow, Ride, boldly ride,\" The shade replied, — \"If you seek for Eldorado!\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "You are not wrong, who deem That my days have been a dream; Yet if hope has flown away In a night, or in a day, In a vision, or in none, Is it therefore the less gone? All that we see or seem Is but a dream within a dream.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "O God! Can I not save ''One'' from the pitiless wave? ''Is ''all'' that we see or seem But a dream within a dream?'", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Thank Heaven! the crisis — The danger is past, And the lingering illness Is over at last — And the fever called \"Living\" Is conquered at last.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Keeping time, time, time, In a sort of Runic rhyme, To the tintinnabulation that so musically wells From the bells, bells, bells, bells, Bells, bells, bells.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Hear the mellow wedding bells Golden bells! What a world of happiness their harmony foretells Through the balmy air of night How they ring out their delight!", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "I attacked with great resolution the editorial matter, and, reading it from beginning to end without understanding a syllable, conceived the possibility of its being Chinese, and so re-read it from the end to the beginning, but with no more satisfactory result.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Believe nothing you hear, and only one half that you see.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Lo! Death has reared himself a throne In a strange city lying alone Far down within the dim West, Where the good and the bad and the worst and the best Have gone to their eternal rest.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "So blend the turrets and shadows there That all seem pendulous in air, While from a proud tower in the town Death looks gigantically down.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Words have no power to impress the mind without the exquisite horror of their reality.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "If you still think me mad, you will think so no longer when I describe the wise precautions I took for the concealment of the body. The night waned, and I worked hastily, but in silence. First of all I dismembered the corpse. I cut off the head and the arms and the legs.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Villains!\" I shrieked, \"dissemble no more! I admit the deed! — tear up the planks! — here, here! — it is the beating of his hideous heart!\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "There is something in the unselfish and self-sacrificing love of a brute, which goes directly to the heart of him who has had frequent occasion to test the paltry friendship and gossamer fidelity of mere Man.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "I grew, day by day, more moody, more irritable, more regardless of the feelings of others. I suffered myself to use intemperate language to my wife. At length, I even offered her personal violence.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "If you wish to forget anything on the spot, make a note that this thing is to be remembered.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "How many good books suffer neglect through the inefficiency of their beginnings!", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "In reading some books we occupy ourselves chiefly with the thoughts of the author; in perusing others, exclusively with our own.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Were I called on to define, ''very'' briefly, the term \"Art,\" I should call it \"the reproduction of what the Senses perceive in Nature through the veil of the soul.\" The mere imitation, however accurate, of what ''is'' in Nature, entitles no man to the sacred name of \"Artist\".", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "That man is not truly brave who is afraid either to seem or to be, when it suits him, a coward.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Once upon a midnight dreary, while I pondered, weak and weary, Over many a quaint and curious volume of forgotten lore, While I nodded, nearly napping, suddenly there came a tapping, As of some one gently rapping, rapping at my chamber door.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Ah, distinctly I remember it was in the bleak December; And each separate dying ember wrought its ghost upon the floor.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Deep into that darkness peering, long I stood there, wondering, fearing, Doubting, dreaming dreams no mortal ever dared to dream before.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Ghastly grim and ancient Raven wandering from the Nightly shore — Tell me what thy lordly name is on the Night's Plutonian shore!\" Quoth the Raven, \"Nevermore.\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Doubtless,\" said I, \"what it utters is its only stock and store, Caught from some unhappy master whom unmerciful Disaster Followed fast and followed faster till his songs one burden bore.\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Prophet!\" said I, \"thing of evil! — prophet still, if bird or devil!\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "\"Get thee back into the tempest and the Night's Plutonian shore! Leave no black plume as a token of that lie thy soul hath spoken! Leave my loneliness unbroken! — quit the bust above my door! Take thy beak from out my heart, and take thy form from off my door!\" Quoth the Raven, \"Nevermore.\"", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "And the Raven, never flitting, still is sitting, ''still'' is sitting On the pallid bust of Pallas just above my chamber door.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Beauty is the sole legitimate province of the poem.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Now the object Truth, or the satisfaction of the intellect, and the object Passion, or the excitement of the heart, are, although attainable to a certain extent in poetry, far more readily attainable in prose.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "The death then of a beautiful woman is unquestionably the most poetical topic in the world, and equally is it beyond doubt that the lips best suited for such topic are those of a bereaved lover.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "Thus I pacified Psyche and kissed her, And tempted her out of her gloom.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "A poem deserves its title only inasmuch as it excites, by elevating the soul.", Author = "Edgar Allan Poe" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Edgar_Allan_Poe", Text = "I would define, in brief, the Poetry of words as the Rhythmical Creation of Beauty. Its sole arbiter is taste. With the intellect or with the conscience, it has only collateral relations. Unless incidentally, it has no concern whatever either with duty or with truth.", Author = "Edgar Allan Poe" },
